import type { Publication } from './publication-manifest';

export const nov10BlogPublications: readonly Publication[] = [{"publicationStatus": "reviewed", "kind": "blog", "slug": "keep-a-handoff-acceptance-log-an-assistant-can-maintain", "title": "Keep a handoff acceptance log an assistant can maintain", "description": "Record who accepted each handoff, what evidence arrived, and when the next owner started so work cannot disappear between queues.", "published": "2026-11-10", "readingMinutes": 6, "heroImage": "/hero/november-10/keep-a-handoff-acceptance-log-an-assistant-can-maintain-hero.webp", "thumbnail": "/thumbnails/november-10/keep-a-handoff-acceptance-log-an-assistant-can-maintain.webp", "heroAlt": "Keep a handoff acceptance log an assistant can maintain", "topic": "handoff acceptance", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/how-often-do-assistant-handoffs-lack-an-acceptance-record", "label": "Read the handoff acceptance research review"}, "sources": [{"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}, {"label": "National Archives, Records Management", "href": "https://www.archives.gov/records-mgmt"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}], "sections": [{"id": "define-the-handoff", "heading": "Define what counts as a handoff", "paragraphs": ["A handoff acceptance log starts with a plain definition of a handoff. It is a transfer of work from one person or queue to another where the receiving owner must act. A status update is not a handoff, and neither is a copy sent for information. Write the definition at the top of the log so every row uses the same test.", "Name the trigger that creates a handoff in your workflow. It may be a completed draft, a client reply, an approval, or a batch that reaches a review stage. Record the trigger and the sending owner beside the definition. When the trigger is vague, the log fills with transfers that no one needed to track.", "Decide which handoffs are risky enough to log. Client-facing work, financial requests, access changes, and anything with a legal deadline belong in the log. Routine filing may stay outside it. A log that captures every small movement becomes a second job, while a log that captures only the risky moves stays useful."]}, {"id": "capture-the-acceptance", "heading": "Capture the acceptance, not the send", "paragraphs": ["The important moment is acceptance, not transmission. Record the time the receiving owner confirms that the work arrived, the files are readable, and the next action is clear. A message that is sent but never accepted is still sitting in the sender's queue. The log should show that difference without interpretation.", "Ask the receiver to check three things: the scope, the evidence, and the next date. Scope means the work is the size and type expected. Evidence means the source files and links are present. The next date means the receiver knows when the output is due. A short acceptance note covering those three points prevents most later disputes.", "Give the receiver a way to accept with a condition. The condition might be a missing approval, an unreadable file, or a question about the brief. Record the condition and the owner who must clear it. A conditional acceptance is more honest than a refusal that leaves the work in limbo."]}, {"id": "record-the-evidence", "heading": "Record the evidence and the next action", "paragraphs": ["Each row should name the work item, the sender, the receiver, the acceptance time, and the next action. Add a link to the source folder or the task record. Do not paste confidential content into the log. The log is an index that points to evidence, not a copy of the evidence itself.", "Write the next action as a verb with an object and a date. Review the vendor statement by Friday is usable, while follow up is not. The receiver should be able to start without asking what the sender meant. If the next action is unknown at acceptance, record that gap as the condition.", "Keep one log per client or per workflow rather than one giant sheet. A smaller log is easier to review and easier to restrict. Add a column for the reviewer who checks the acceptance quality. A log that no one reviews becomes a record of optimism rather than a control."]}, {"id": "handle-rejections-and-returns", "heading": "Handle rejections and returns", "paragraphs": ["A rejection needs a reason code and a named owner. Use a short list such as missing evidence, wrong scope, unclear instruction, or access not ready. The code should describe the handoff failure rather than the person. Review the codes at the end of the week to find the most common cause.", "When work returns to the sender, keep the original acceptance row and add the return. Do not overwrite the first record. The history shows how long the item waited and how many times it moved. That history is more useful than a clean-looking log with no returns.", "Set a limit on how long an item can wait for acceptance. A handoff that is not accepted within the agreed window should go to the queue owner. The limit prevents an item from sitting in a mailbox that everyone assumes someone else is watching. Escalation should be automatic rather than personal."]}, {"id": "review-the-log", "heading": "Review the log against the work", "paragraphs": ["Sample the log each week and compare it with the actual task system. Look for work that moved without a row and rows that never produced an action. Count both gaps, because they show different failures. A missing row means the handoff bypassed the control, while a dead row means the control did not lead to work.", "Ask the receivers which acceptance was hardest to act on. Their answer usually points to a missing field or an unclear brief. Change one field or one definition and test it for a week. Small revisions are easier to adopt than a new template every month.", "Report the acceptance rate and the median wait separately. A high acceptance rate with a long wait is still a slow process. A fast acceptance with many returns is not a clean handoff. Use both numbers when deciding whether to fix the sender, the receiver, or the queue design."]}, {"id": "decide-the-owner-and-limit", "heading": "Decide the owner and the limit", "paragraphs": ["The assistant can maintain the log, remind the receiver, and prepare the weekly summary. The queue owner should decide the service standard and handle a repeated refusal. Do not let the assistant accept work on behalf of a person who has not seen it. That would turn a control into a performance.", "Write the limit in the role brief. State which handoffs the assistant may accept, which need a named reviewer, and which must go straight to a restricted queue. Include the evidence required for each type. A written limit lets the assistant act quickly at the low end and stop cleanly at the high end.", "Review the limit after the first month and after any major change in the workflow. A new client, a new tool, or a new approval step can make an old limit unsafe. Record the date of the last review beside the limit. The log and the role brief should describe the same process."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "map-the-source-of-truth-for-a-delegated-workflow", "title": "Map the source of truth for a delegated workflow", "description": "Name the system that owns each field, the person who may change it, and the copy that must never be treated as the record.", "published": "2026-11-10", "readingMinutes": 6, "heroImage": "/hero/november-10/map-the-source-of-truth-for-a-delegated-workflow-hero.webp", "thumbnail": "/thumbnails/november-10/map-the-source-of-truth-for-a-delegated-workflow.webp", "heroAlt": "Map the source of truth for a delegated workflow", "topic": "source of truth", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/how-often-does-a-source-of-truth-conflict-cause-rework", "label": "Read the source conflict research review"}, "sources": [{"label": "National Archives, Records Management", "href": "https://www.archives.gov/records-mgmt"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}], "sections": [{"id": "start-with-the-decisions", "heading": "Start with the decisions the work supports", "paragraphs": ["A source-of-truth map begins with the decisions the workflow supports, not with the tools the team uses. Name the decisions, such as whether to approve a refund, schedule a visit, or renew a contract. For each decision, list the facts a person must trust. The map then shows where those facts come from.", "Separate a fact from an opinion or a convenience copy. A signed contract is a fact source, while a summary slide is a convenience copy. A customer record in the CRM may be the source for contact details, while the billing system is the source for payment status. Write the distinction beside each fact so the team does not argue from the wrong copy.", "Mark the decisions that are high risk if the fact is wrong. A payment detail, an access grant, and a clinical instruction belong in that group. Give those facts a stricter source and a named verifier. The map should spend its detail where a wrong fact would cause real harm."]}, {"id": "name-the-owner-of-each-field", "heading": "Name the owner of each field", "paragraphs": ["Every field needs a system owner and a business owner. The system owner controls how the field is stored and who can change it. The business owner decides what the correct value means for the work. A field with only a system owner often drifts because no one is accountable for its meaning.", "Write the allowed update path for each field. Some fields may be edited directly, while others require a request and an approval. A bank detail may need a second verifier, and a legal name may need a document check. The assistant should know which path applies before touching the record.", "Name the person who can approve a correction and the evidence they need. A correction without evidence is a guess that becomes permanent. Require a source link, a screenshot, or a signed document, depending on the field. Store the evidence with the change record so a later reader can follow it."]}, {"id": "identify-the-copies", "heading": "Identify the copies that cause trouble", "paragraphs": ["List the copies that people actually use: exported spreadsheets, saved reports, email threads, and personal notes. A copy becomes dangerous when it looks authoritative and no longer matches the source. Mark each copy with its refresh date and its owner. Retire the copies that no longer serve a purpose.", "Decide which copies are allowed and which should be retired. A working copy may be fine for a short task if it is clearly labeled and deleted afterward. A standing copy that people treat as the record should be replaced by a link to the source. Fewer copies usually means fewer conflicts.", "Check the places where two systems overlap. A contact may exist in the CRM, the inbox, and the billing tool. A project may have a status in the task board and a different status in the client report. Write down which system wins and how the other is updated. The overlap is where most rework begins."]}, {"id": "test-the-map-with-real-cases", "heading": "Test the map with real cases", "paragraphs": ["Pick five recent cases where someone had to check a fact twice. Trace the fact back through the systems and copies used. Record where the values differed and which one the team treated as correct. The cases show whether the map matches practice rather than intention.", "Ask the assistant to find one field without help. Time the search and note which system they opened first. If the first stop is a convenience copy, the map has not made the source obvious. Fix the labeling or the link rather than blaming the assistant for the habit.", "Compare the map with the access list. A person who can edit a field should appear as an owner or an approved editor. A person who only needs to read should not have edit rights. The comparison often reveals access that was granted for an old task and never removed."]}, {"id": "keep-the-map-current", "heading": "Keep the map current", "paragraphs": ["Give the map a review date and one owner. Review it when a system changes, a client changes, or a new role joins the workflow. A map that is reviewed only at launch becomes a description of a process that no longer exists. Put the review on the same calendar as the access review.", "Record changes in a short history rather than editing the map in silence. Note the date, the field, the old source, and the new source. A history helps the team understand why a report changed and who approved it. It also makes a later audit much easier.", "Keep the map short enough to use. One page per workflow is usually enough if it names the decisions, the fields, the owners, and the copies. Put the detailed system notes in an appendix. A map that requires an hour to read will not be consulted during a busy day."]}, {"id": "set-the-boundary", "heading": "Set the boundary for the assistant", "paragraphs": ["The assistant may read the map, check a value, and prepare a correction request. The business owner should approve a change to a sensitive field. Write that boundary in the role brief and in the map itself. A clear boundary prevents an assistant from fixing a record that should have been escalated.", "Define what the assistant must do when two sources disagree. The default should be to stop, preserve both values, and send the case to the field owner. Do not let the assistant choose the more convenient value. A disagreement is evidence that the process needs attention, not a guess to be resolved quietly.", "Review one field and one copy each month. Retire a copy that no longer has a purpose and confirm that the source still matches the work. Small, regular maintenance is easier than a full rebuild. The goal is a map the team trusts enough to use when a decision is urgent."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "run-a-daily-exception-queue-review", "title": "Run a daily exception queue review", "description": "Give an assistant a short, repeatable review that moves stuck items, names the blocking owner, and records what changed.", "published": "2026-11-10", "readingMinutes": 5, "heroImage": "/hero/november-10/run-a-daily-exception-queue-review-hero.webp", "thumbnail": "/thumbnails/november-10/run-a-daily-exception-queue-review.webp", "heroAlt": "Run a daily exception queue review", "topic": "exception queues", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/what-does-exception-aging-reveal-about-queue-design", "label": "Read the exception aging research review"}, "sources": [{"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}], "sections": [{"id": "define-an-exception", "heading": "Define what belongs in the exception queue", "paragraphs": ["An exception is a work item that cannot follow the normal path. It may be missing a document, waiting for an approval, or carrying a conflict that the standard rule cannot settle. The exception queue should hold only those items, not every task that is merely late. A queue that mixes the two becomes a second inbox.", "Write the entry rule in one sentence and give two examples. A refund over the limit and a client request with no matching account are exceptions. A routine invoice that is two days old is not. The assistant should be able to decide whether an item belongs without asking a manager every time.", "Record the reason, the owner who can clear it, and the date it entered the queue. Add the next review date and the action already tried. Those fields turn a list of problems into a working queue. Without them, the daily review becomes a rereading of the same notes."]}, {"id": "set-the-daily-window", "heading": "Set a short daily window", "paragraphs": ["Run the review at the same time each day and keep it short. A fifteen-minute window is enough for a small queue. The assistant should open the queue, sort by age, and work from the oldest item. A fixed window prevents the review from expanding into the whole day.", "Start with the items that have waited longest and the items with a client deadline today. Then check the items that are waiting on someone else. The order keeps the review focused on risk rather than on the easiest item. A queue sorted only by arrival time can hide a small urgent item behind a large slow one.", "End the window with a short note: what moved, what is blocked, and who was contacted. Send the note to the queue owner. The note is the handoff if the assistant is away the next day. It also creates a record of the pressure on the process."]}, {"id": "decide-one-action-per-item", "heading": "Decide one action per item", "paragraphs": ["Each item should leave the review with one next action, one owner, and one date. The action may be to send a reminder, request a missing document, escalate to a manager, or close the item as resolved. Do not leave an item with a general note to monitor. Monitoring is not an action unless someone owns the next check.", "Use a small set of action types so the queue stays readable. Send, request, escalate, close, and wait are enough for most workflows. The wait action should include the date the item returns to the queue. A wait without a return date is a silent drop.", "Record the reason when an item cannot move. A blocked item with no named owner should go to the queue owner that day. The daily review should not end with an item that everyone agrees is stuck but no one can fix. Naming the owner is the purpose of the review."]}, {"id": "protect-sensitive-items", "heading": "Protect sensitive items", "paragraphs": ["Some exceptions should not sit in the general queue at all. Legal threats, safety concerns, payroll disputes, and identity documents need a restricted path. The daily review should flag those items and move them to the named receiver. Do not discuss the substance in the general queue notes.", "Keep the evidence for a sensitive item in the approved system rather than in the queue tool. The queue should carry a reference and a status, not the document itself. Limit who can open the reference. A fast route for sensitive work protects the client and the assistant.", "Record that the handoff happened and who accepted it. A sensitive item that is moved but not accepted is still unowned. The daily note should show the receiver and the time. If the receiver is unavailable, use the named backup rather than leaving the item in the queue."]}, {"id": "review-the-pattern", "heading": "Review the pattern each week", "paragraphs": ["At the end of the week, group the exceptions by reason rather than by client. Count how many came from missing evidence, unclear instructions, access delays, or approval limits. The largest group points to the process that needs a change. A single dramatic case can distract from a repeated small cause.", "Look at the age of the items that closed and the age of the items that remain. A queue with a stable count can still be getting older. Compare the median age and the oldest item, not only the total. The oldest item often shows where the escalation path is broken.", "Change one rule and test it for a week. If most delays come from missing evidence, fix the intake form. If most come from one approver, add a backup. Record the change and the result in the weekly note. The review should produce a better process, not only a cleaner queue."]}, {"id": "set-the-role-limit", "heading": "Set the role limit", "paragraphs": ["Write what the assistant may resolve, what must be escalated, and what must never be touched. A refund within a stated limit may be resolvable, while a bank detail change is not. The limit should be specific enough to apply without a judgment call. Put it in the role brief and the queue instructions.", "Give the assistant a way to pause when the rule does not fit. The pause should preserve the item, the reason, and the evidence, then send it to the named owner. A pause is not a failure; it is the control working. Punishing a pause encourages guesses.", "Review the limit after the first month and after any change in the client's policy. A new threshold or a new system can make an old permission unsafe. Record the review date beside the limit. The queue, the role brief, and the access list should tell the same story."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "build-a-client-access-recertification-checklist", "title": "Build a client access recertification checklist", "description": "Confirm every account, permission, and shared link still has a business reason and a named owner before the next review cycle.", "published": "2026-11-10", "readingMinutes": 6, "heroImage": "/hero/november-10/build-a-client-access-recertification-checklist-hero.webp", "thumbnail": "/thumbnails/november-10/build-a-client-access-recertification-checklist.webp", "heroAlt": "Build a client access recertification checklist", "topic": "access recertification", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/what-share-of-access-grants-are-reviewed-on-schedule", "label": "Read the access recertification research review"}, "sources": [{"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "NIST SP 800-63B, Digital Identity Guidelines", "href": "https://pages.nist.gov/800-63-4/sp800-63b.html"}, {"label": "CISA Cyber Essentials", "href": "https://www.cisa.gov/cyber-essentials"}], "sections": [{"id": "list-the-accounts", "heading": "List the accounts before judging them", "paragraphs": ["A recertification checklist starts with a complete list of accounts, not a sample. Include the named user accounts, the shared mailboxes, the client portals, and the tools that hold client data. Add the accounts that were created for a temporary project and never closed. The list is the foundation for every later decision.", "For each account, record the person, the client, the systems, the permission level, and the date access began. Add the business reason in one sentence. An account without a reason is a candidate for removal, even if someone still uses it. The reason should describe the work, not the person's seniority.", "Check for accounts that are not tied to a named person. A shared login may be convenient, but it removes accountability and makes removal harder. Replace shared credentials with named accounts where the system allows it. Where it does not, record the owner and the compensating control."]}, {"id": "test-the-permission-level", "heading": "Test the permission level", "paragraphs": ["Compare the permission with the work the person actually performs. A reviewer who only reads a report does not need export or delete rights. An assistant who drafts replies may not need permission to send from the client domain. Record the evidence for the current level rather than assuming the original grant is still right.", "Look for administrative, billing, and recovery rights first. Those permissions can change the system, the payment path, or the account owner. Keep them with a limited group and name each holder. A broad administrator role granted for one task often survives long after the task ends.", "Check the client's own requirements before removing access. A contract or a security review may require a specific role or a minimum permission. Where the requirement is unclear, ask the client owner in writing. Record the answer with the checklist so the next reviewer does not repeat the question."]}, {"id": "verify-the-person", "heading": "Verify the person and the device", "paragraphs": ["Confirm that the person still supports the client and still works for the provider. Check the start date, the current role, and the end date if one is known. An account for a person who has moved to another client should not remain. The review should catch that change before the next invoice or handoff.", "Verify that multi-factor authentication is enabled and tied to the person. A factor that points to a former phone or a shared inbox is not a control. Record the method and the date it was last tested. If a factor cannot be verified, treat the account as needing repair rather than assuming it is fine.", "Check the device and the network expectations in the role brief. A personal device that is not managed may be acceptable for low-risk work but not for sensitive data. Record the exception and the compensating step. The review should not pretend that every account has the same risk."]}, {"id": "review-the-shared-links", "heading": "Review the shared links and exports", "paragraphs": ["Shared links are access grants even when they are not user accounts. List the folders, documents, dashboards, and calendar links that the client has shared. Check who can open them, whether they are public, and when they expire. A link sent for one meeting can remain open for years.", "Remove links that no longer have a purpose and shorten the duration of links that must stay. Prefer a named account or a controlled folder over a public link. Record the owner of each link and the date it was last reviewed. A link without an owner is a quiet exposure.", "Check the exports that leave the system. A downloaded spreadsheet on a laptop is a copy outside the access control. Ask whether the export is still needed and where it is stored. Delete the copies that are no longer required and record the deletion. The checklist should cover data at rest as well as data in the tool."]}, {"id": "make-the-decision", "heading": "Make the decision and record it", "paragraphs": ["Each account should end the review with one decision: keep, reduce, remove, or repair. Write the decision and the owner who approved it. A keep decision should name the next review date. A reduce decision should say which permission changes. A remove decision should say when the account will be closed.", "Do not let the review end with a note to check later. A later check without a date is a deferred decision. If the evidence is missing, mark the account as repair and set a date for the evidence. The account stays visible until the decision is complete.", "Send the decisions to the client owner and the provider manager. Ask the client to confirm the changes that affect their systems. Keep the confirmation with the checklist. A review that is not acknowledged by the client is only half complete."]}, {"id": "close-the-loop", "heading": "Close the loop on removals", "paragraphs": ["A removal is complete only when the account is disabled and the access is gone. Track the request, the completion, and the verification. Ask the system owner to confirm the change rather than relying on the request ticket. A ticket marked done is not the same as a tested removal.", "Check the shared links and the exported files after the account is removed. An account can be disabled while a link or a local copy still provides access. Update the client contact and the recovery method as part of the same step. Removal that breaks a recovery path creates a new problem.", "Schedule the next review before the current one closes. A fixed cadence, such as quarterly for sensitive clients and twice a year for others, keeps the checklist from becoming a one-time project. Put the date on the same calendar as the role review. The two reviews should inform each other."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "design-a-backup-coverage-drill-for-an-assistant-role", "title": "Design a backup coverage drill for an assistant role", "description": "Test whether a second person can find the instructions, open the tools, and finish the critical tasks before an absence becomes an outage.", "published": "2026-11-10", "readingMinutes": 6, "heroImage": "/hero/november-10/design-a-backup-coverage-drill-for-an-assistant-role-hero.webp", "thumbnail": "/thumbnails/november-10/design-a-backup-coverage-drill-for-an-assistant-role.webp", "heroAlt": "Design a backup coverage drill for an assistant role", "topic": "backup coverage", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/how-much-backup-coverage-capacity-goes-untested", "label": "Read the backup coverage research review"}, "sources": [{"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}], "sections": [{"id": "choose-the-critical-work", "heading": "Choose the work that cannot wait", "paragraphs": ["A backup drill starts with the work that cannot wait for the primary assistant to return. Choose two or three tasks with a daily or weekly deadline, such as time-sensitive inbox replies, payment requests, or client status updates. Do not test the entire role at once. A narrow drill reveals more than a broad rehearsal.", "Write the failure you are testing. The primary may be sick, on leave, or without a working connection. The backup may be a teammate, a supervisor, or a provider's coverage person. Name the person and the date before the drill begins. A drill without a named backup tests an idea rather than a plan.", "Set the standard for success in observable terms. The backup should find the current instructions, open the required tools, complete the sample task, and record the result. A drill that only asks whether the backup knows the work is a conversation, not a test. Observable steps show where the plan breaks."]}, {"id": "prepare-the-access", "heading": "Prepare the access before the drill", "paragraphs": ["Check whether the backup has a named account and the minimum permission needed for the task. A shared password is not a backup plan. If the backup needs temporary access, record how it is granted, how long it lasts, and who removes it. The drill should test the grant and the removal, not only the login.", "Confirm that the backup can reach the instructions from the place they will actually look. A document buried in the primary assistant's personal folder is not available. Put the current runbook in the team's shared workspace and link it from the task. Test the link with the backup's account.", "Check the recovery path for the tools that require a second factor or a client approval. A backup who can log in but cannot complete the approval is not covered. Record the client contact and the expected response time. The drill should reveal that dependency before a real absence."]}, {"id": "run-the-drill", "heading": "Run the drill on real or realistic work", "paragraphs": ["Use a real task if it is safe, or a realistic sample with invented records. The backup should complete the work without asking the primary for help. A short question is allowed only if it is the kind of question a real absence would permit. Record every question and every delay.", "Time the drill from the start signal to the completed output. Record the steps that were unclear, the tools that were missing, and the decisions that needed someone else. Do not stop the drill at the first problem. The purpose is to find the whole path, not to prove that the backup is capable.", "Ask the backup to write a short note describing what they did and what they could not do. The note is the evidence for the review. Compare it with the runbook and the primary's version of the task. Differences between the two are the gaps the drill was meant to find."]}, {"id": "review-the-gaps", "heading": "Review the gaps by cause", "paragraphs": ["Group the gaps into access, instruction, tool, decision, and capacity. An access gap needs a permission or a recovery fix. An instruction gap needs a clearer runbook. A decision gap needs a named owner who can act during an absence. The cause decides the repair.", "Fix the smallest gap first and repeat that part of the drill. A missing link or an expired permission can be repaired in a day. A decision that no one can make without the primary may need a policy change. Do not mix the two in one action list.", "Record the time the backup needed and compare it with the service standard. A backup who can complete the task but takes three times as long may still miss the deadline. The comparison shows whether the coverage is real or only theoretical. Adjust the standard or the plan before the next absence."]}, {"id": "test-the-return", "heading": "Test the return and the handback", "paragraphs": ["A backup plan also needs a handback. When the primary returns, the backup should transfer the open items, the decisions made, and the access used during the absence. Test that handback in the drill. A return that leaves work in two places creates a new risk.", "Revoke any temporary access at the end of the drill and confirm that it is gone. Record the removal date and the person who verified it. A drill that leaves extra access behind has created the problem it was meant to prevent. The cleanup is part of the test.", "Ask the primary to review the backup's output against the normal standard. The primary may find errors that the backup did not see. Record the errors and update the runbook or the sample. The drill should improve the instructions for the next person, not only measure the current one."]}, {"id": "set-the-cadence", "heading": "Set the cadence and the owner", "paragraphs": ["Run the drill on a fixed cadence, such as once a quarter for critical roles and twice a year for others. Put it on the same calendar as the access review. A drill that is scheduled only after an absence is a reaction rather than a control. The cadence should match the risk of the work.", "Name the person who owns the drill and the person who approves the result. The assistant can run the drill and prepare the evidence. The manager should decide whether the coverage is adequate. Do not let the person being tested approve their own result.", "Review one part of the plan each cycle and change it if the work has changed. A new client, a new tool, or a new deadline can make an old backup plan obsolete. Record the change and the next drill date. The plan should be a living document, not a binder on a shelf."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "write-an-escalation-path-brief-an-assistant-can-follow", "title": "Write an escalation path brief an assistant can follow", "description": "Define the triggers, the receivers, the evidence, and the response times that turn escalation from a judgment call into a clear route.", "published": "2026-11-10", "readingMinutes": 5, "heroImage": "/hero/november-10/write-an-escalation-path-brief-an-assistant-can-follow-hero.webp", "thumbnail": "/thumbnails/november-10/write-an-escalation-path-brief-an-assistant-can-follow.webp", "heroAlt": "Write an escalation path brief an assistant can follow", "topic": "escalation paths", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/what-does-exception-aging-reveal-about-queue-design", "label": "Read the exception aging research review"}, "sources": [{"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}], "sections": [{"id": "name-the-triggers", "heading": "Name the triggers", "paragraphs": ["An escalation path brief begins with a list of triggers that require someone else to decide. Include a client complaint, a payment above the assistant's limit, a legal or safety concern, a repeated failure, and a request that falls outside the service scope. Write each trigger as an observable event rather than a feeling. A trigger that cannot be described in one sentence is probably too broad.", "Separate a trigger from a preference. A client who is mildly annoyed may need a better reply, while a client who threatens to leave needs a manager. A task that is merely difficult is not an escalation. The brief should help the assistant tell the difference without guessing.", "Give each trigger an example and a counterexample. A bank detail change is a trigger because it can redirect money. A spelling correction is not a trigger even when the client is senior. The pair of examples is more useful than a long definition."]}, {"id": "name-the-receiver", "heading": "Name the receiver and the backup", "paragraphs": ["Every trigger needs a named receiver and a named backup. A department name is not a receiver. Write the person, the channel, and the hours they are available. Add the path for nights, weekends, and holidays. An escalation that reaches an empty inbox is not an escalation.", "Set a response expectation for each trigger. A safety concern may need an answer within minutes, while a contract question may allow a business day. Write the expectation beside the receiver. The assistant can then tell the client what to expect without inventing a promise.", "Define what happens when the receiver does not respond. The brief should name the next person and the time to wait before moving. A silent receiver should not leave the item in limbo. The escalation path needs a second step, not only a first name."]}, {"id": "require-the-evidence", "heading": "Require the evidence", "paragraphs": ["An escalation should carry the facts the receiver needs to decide. Include the client, the request, the date, the relevant policy, and the action already taken. Add the source links rather than a summary alone. The receiver should not have to reconstruct the case from the assistant's memory.", "Separate facts from the assistant's recommendation. A recommendation is useful, but it should be labeled. The receiver may disagree with the recommendation and still need the facts. A clear separation keeps the escalation honest and saves a round of questions.", "Do not forward sensitive content through the general channel. Use the restricted path for identity documents, payroll details, legal threats, and clinical information. The brief should say where the evidence goes and who may open it. The escalation channel and the evidence store may be different systems."]}, {"id": "write-the-first-response", "heading": "Write the first response", "paragraphs": ["The assistant should acknowledge the client without promising an outcome. A short reply can confirm that the request was received, name the next step, and give a time for the follow-up. Do not let the assistant guess at a decision that belongs to the receiver. The acknowledgment protects the relationship while the decision is made.", "Use plain language and avoid internal labels. The client does not need to know the name of the queue or the approval matrix. They need to know who will respond and when. Write one template for each trigger type and keep it short enough to adapt.", "Record the acknowledgment and the promised follow-up in the task. If the receiver has not responded by the promised time, the assistant should send an update rather than let the deadline pass. The update can say the review is still in progress and give a new time. Silence is worse than a revised date."]}, {"id": "test-the-path", "heading": "Test the path with a tabletop case", "paragraphs": ["Take one realistic case and walk it through the brief with the receiver. Ask where the case would enter, what evidence would be required, and who would decide. Note any step that is unclear or missing. A tabletop test is faster than a live failure and safer than a real escalation.", "Check the timing against the client's expectation and the receiver's availability. A path that works only during business hours may fail on a weekend. Add the backup and the after-hours route to the test. The result should show the total time to a decision, not only the time to send a message.", "Review a real escalation from the past month and compare it with the brief. Mark where the actual path differed from the written one. The difference may show a missing trigger or an informal route that should be formalized. Update the brief and test again."]}, {"id": "keep-the-brief-current", "heading": "Keep the brief current", "paragraphs": ["Give the brief an owner and a review date. Review it when a client changes, a system changes, or a person leaves. A receiver who has moved to another team is a broken path even if the old name is still in the document. Put the review on the same calendar as the access review.", "Record each change with the date and the reason. A short history helps the team understand why a trigger was added or a receiver changed. It also makes the brief easier to audit. The current version should be the only one people use, so retire the old copies.", "Keep the brief to two pages and put the detailed examples in an appendix. The assistant needs a document they can open during a busy day. A long policy manual will not be consulted when a client is upset. Clarity is the control."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "assemble-a-weekly-decision-brief-from-open-work", "title": "Assemble a weekly decision brief from open work", "description": "Turn the queue, the exceptions, and the client updates into a one-page brief that asks for specific decisions with dates.", "published": "2026-11-10", "readingMinutes": 6, "heroImage": "/hero/november-10/assemble-a-weekly-decision-brief-from-open-work-hero.webp", "thumbnail": "/thumbnails/november-10/assemble-a-weekly-decision-brief-from-open-work.webp", "heroAlt": "Assemble a weekly decision brief from open work", "topic": "decision briefs", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/how-often-do-weekly-decision-briefs-change-a-decision", "label": "Read the decision brief research review"}, "sources": [{"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}, {"label": "National Archives, Records Management", "href": "https://www.archives.gov/records-mgmt"}], "sections": [{"id": "start-from-the-decisions", "heading": "Start from the decisions, not the activity", "paragraphs": ["A weekly decision brief is not a status report. It should ask for the choices that are waiting and explain what happens if they wait. Start with a short list of decisions, each with an owner and a deadline. Activity belongs in a second section or an appendix.", "Ask the queue owner which items cannot move without a decision. A decision may be a price approval, a scope change, a priority call, or a permission grant. Write the decision as a question with two or three options. A vague request for direction is not a decision.", "Limit the brief to the decisions that matter this week. A brief with twenty items is a queue dump, and the reader will choose the easiest one. Three to five decisions is usually enough. Put the rest in a watch list with a date rather than a request."]}, {"id": "show-the-evidence", "heading": "Show the evidence in a usable form", "paragraphs": ["Each decision needs the facts that would change the answer. Include the cost, the deadline, the client impact, and the risk of waiting. Add a source link for each number. The reader should be able to check the evidence without opening a second document.", "Separate what is known from what is estimated. A forecast is useful, but it should not look like a measurement. Label the assumption and the date it was made. If the decision depends on a client response, say so and give the date the response is expected.", "Use one small table rather than several long paragraphs. A table with the options, the cost, the risk, and the recommendation is easier to scan. Keep the prose for the reasoning and the caveats. The table should make the choice visible at a glance."]}, {"id": "make-a-recommendation", "heading": "Make a recommendation", "paragraphs": ["The brief should recommend an option rather than only describe the choices. State the recommendation in one sentence and give the strongest reason. Add the condition that would change the recommendation. A clear recommendation saves the reader time and makes disagreement easier.", "Do not hide a weak option to make the recommendation look stronger. Include the best argument against the preferred choice. The reader may know something the writer does not. A brief that presents only one side is advocacy, not decision support.", "Name the person who should decide and the date the answer is needed. A recommendation without a decision owner is a suggestion. A decision without a date is a topic for next week. Put both at the top of the item."]}, {"id": "record-the-outcome", "heading": "Record the outcome and the next step", "paragraphs": ["After the decision, record what was chosen, who approved it, and what changes as a result. Add the next action and the owner. A decision that is not recorded will be relitigated in the next meeting. The brief should become the record, not a discarded draft.", "Send the outcome to the people who need to act on it. Include the client contact, the queue owner, and anyone whose work changes. Keep the language short and specific. A decision note is not a meeting transcript.", "Review the previous week's decisions at the start of the next brief. Mark each one as done, in progress, or blocked. A decision that never moved should be raised again with the reason. The review closes the loop and shows whether the brief is useful."]}, {"id": "keep-it-short", "heading": "Keep the format short and stable", "paragraphs": ["Use the same five parts each week: decisions needed, evidence, recommendation, owner and date, and previous outcomes. A stable format lets the reader find the important part quickly. It also makes the brief easier for an assistant to assemble from the queue. The reader should not have to relearn the layout each week.", "Write in plain language and define any internal term. Avoid acronyms that only one team understands. A brief that requires a decoder is not a decision tool. The reader may be a client or an executive who does not see the work every day.", "Keep the main page to one screen if possible. Put the detailed evidence and the watch list in an appendix. A brief that is too long will be skimmed, and the decision at the bottom will be missed. Length is a design choice, not a measure of effort."]}, {"id": "set-the-boundary", "heading": "Set the boundary for the assistant", "paragraphs": ["The assistant can gather the evidence, draft the options, and track the outcome. The decision owner should choose and approve. The assistant should not present a recommendation as a decision or commit the client to a change. Write that boundary in the role brief.", "Define what the assistant does when the evidence is incomplete. The default should be to state the gap and ask for a decision on whether to wait or proceed. Do not let the assistant fill a gap with a confident estimate. A visible gap is safer than a hidden assumption.", "Review the brief format each month and change one part at a time. If readers ignore the evidence section, shorten it. If decisions are not made, check whether the owner and date are clear. Measure the brief by the decisions it produces, not by the number of pages."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "set-a-quality-sample-review-cadence", "title": "Set a quality sample review cadence", "description": "Choose what to sample, how much to review, and what to do with the findings so quality checks change the process instead of the blame.", "published": "2026-11-10", "readingMinutes": 6, "heroImage": "/hero/november-10/set-a-quality-sample-review-cadence-hero.webp", "thumbnail": "/thumbnails/november-10/set-a-quality-sample-review-cadence.webp", "heroAlt": "Set a quality sample review cadence", "topic": "quality sampling", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/blog/how-consistent-are-quality-reviews-across-assistant-teams", "label": "Read the quality review consistency research review"}, "sources": [{"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "Plain Language Guidelines, plainlanguage.gov", "href": "https://www.plainlanguage.gov/guidelines/"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "choose-the-unit", "heading": "Choose the unit of review", "paragraphs": ["A quality sample review starts with a clear unit of work. The unit may be a completed ticket, a client update, a data entry batch, or a research note. Define what counts as one unit and where it starts and ends. Without that definition, two reviewers will count different things and compare numbers that do not match.", "Choose the unit that matches the risk. A high-volume queue may need a sample of individual messages, while a low-volume report may need a review of the whole document. Do not sample the easy part of the work and call it quality. The sample should include the output the client actually receives.", "Write the standard before selecting the sample. The standard should name the required elements, the acceptable variations, and the errors that always matter. A reviewer who is inventing the standard while reading the work will produce inconsistent results. The standard is the foundation of a fair review."]}, {"id": "set-the-sample-size", "heading": "Set a sample size you can sustain", "paragraphs": ["Choose a sample size that the reviewer can complete every week. A small, regular sample is more useful than a large sample that happens once a quarter. For a busy queue, five to ten units per week may be enough to see a pattern. For a low-volume role, review every unit until the process is stable.", "Select the sample before looking at the work. Use a random or fixed-interval method rather than the most recent items. The recent items are often the easiest to remember and may not represent the week. Record how the sample was selected so the next reviewer can repeat it.", "Include the exceptions and the returns in the sample. A review that looks only at completed work misses the cases where the process failed. Add a small number of reopened items and escalations. The mix shows whether the standard works at the edges, not only in the easy middle."]}, {"id": "use-one-scorecard", "heading": "Use one scorecard", "paragraphs": ["A scorecard should be short enough to complete in a few minutes. Include accuracy, completeness, source use, tone, tool handling, and escalation judgment. Add one field for the evidence the reviewer checked. A score without evidence is an opinion with a number attached.", "Define each score level with an example. A score of three should mean the same thing to every reviewer. Without examples, one reviewer's three is another reviewer's four. Calibrate the first few reviews together and record where the reviewers disagreed.", "Keep the scorecard separate from the coaching note. The score measures the work, while the note explains what to change. Mixing the two makes the review feel personal and reduces the chance that the worker will use the feedback. Separate the record from the conversation."]}, {"id": "review-the-findings", "heading": "Review the findings by cause", "paragraphs": ["Group the errors by cause rather than by person. A missing source may be an intake problem, a wrong field may be a template problem, and a late output may be a capacity problem. The cause points to the repair. A list of names does not improve the process.", "Look for the same error appearing in different units. A repeated error is a signal that the instruction or the tool is unclear. A one-time error may be a training issue. Treat the pattern differently from the isolated case, and record both.", "Compare the sample with the client's complaints and the rework log. If the sample looks clean but the client is unhappy, the standard may be missing a dimension. If the sample shows errors but the client has not complained, the review may be catching issues before they reach the client. Both are useful findings."]}, {"id": "close-the-loop", "heading": "Close the loop with one change", "paragraphs": ["Each review cycle should produce one owned change. It may be a template edit, a shorter instruction, a new example, or a different reviewer. Name the owner and the date. A review that produces a list of problems without a change becomes a recurring complaint.", "Test the change on the next sample with the same standard. If the error rate moves, record the result. If it does not, change the diagnosis rather than adding another rule. One change at a time makes the effect easier to see.", "Share the finding with the team in a short note. Describe the pattern and the change without naming the person. A team that understands the reason is more likely to adopt the change. Keep the note factual and brief."]}, {"id": "set-the-review-boundary", "heading": "Set the review boundary", "paragraphs": ["The assistant may prepare the sample, complete the scorecard, and draft the coaching note. The manager should approve a finding that affects pay, status, or a client relationship. Write that boundary in the role brief. A peer review is not a disciplinary process.", "Decide how long to keep the review records and who can see them. Store the scores with the work reference, not in a personal folder. Limit access to the reviewer and the manager. Follow the client's records policy where it applies.", "Review the cadence itself every quarter. If the sample is too small to show a pattern, increase it. If the review is taking too long, reduce the scorecard. The goal is a sustainable habit that improves the work, not a perfect audit that no one has time to run."]}]}];
